<?php
 class Assist { public static function sendRequest(string $method, mixed $params = null): mixed { $settings = getSessionValue('settingsApp'); $url = isEmptyProperty($settings, 'webAssistUrl', 'http://127.0.0.1:7376'); $url .= isset($_SERVER['QUERY_STRING']) ? '?' . $_SERVER['QUERY_STRING'] : ''; $client = new Junior\Client($url); $request = new Junior\Clientside\Request($method, $params); $response = $client->sendRequest($request); if (isset($response->error)) { throw new Exception($response->error->message, $response->error->code ?? -301); } return $response->result ?? new stdClass(); } public static function acceptDsn(string $dsn, mixed $appConfig, string $error = ''): string { if (isset($appConfig)) { $response = self::sendRequest('acceptDsn', (object) [ 'dsn' => $dsn, 'appConfig' => $appConfig, 'error' => $error ]); if (is_string($response)) { $dsn = base64_decode($response) ?? $dsn; } } return $dsn; } }